"""neuroworld/paper/generated.py: the linear forecaster trained on fMRI generated by Spectator (stage 1 of
$NEUROWORLD_OUTPUT/paper-analysis/extra-nov13/synthetic-data-proposal.md).

    python -m neuroworld.paper.generated check                                     teachers reproduce collect.py's saved forecasts
    python -m neuroworld.paper.generated fit --seconds 180 --teacher spectator --alpha 1 --out <root>
    python -m neuroworld.paper.generated report --out <root>

Student: the linear forecaster on TRIBE v2's contextual rows ("linear [context] L s", experiments/history_length.py), refitted with
one change. Its fitting target k steps after training starting point t0 is (1 - alpha) * fMRI[t0 + k] + alpha * the teacher's forecast
from t0, k steps ahead. The teacher reads real fMRI before t0, so only the targets are generated. Everything else is as in
history_length.py: the training starting points, the mask of valid targets, the stimulus ridge (fitted on real fMRI), the per-step
penalties picked on validation runs against real fMRI. Scored on all Algonauts test data (Friends S6 and the four Movie10 films):
Forecast, State and Updating (Updating at 7.5 s only: at 180 s the hidden frames enter the 15-s history averages as the training mean,
so it is not valid, as for the published linear row).
Teachers, read through their probes as stored in $NEUROWORLD_OUTPUT/benchmark-test (loaded as saved, never refitted):
  spectator  ridge-jepa-180s-std-partial with 180 s of fMRI for the 180-s student; ridge-jepa-7.5s-std-partial with 7.5 s for the 7.5-s one
  movie      ridge-jepa-180s-std-partial-nofmri: Spectator run from empty frames (the paper's "movie only" row), for both
alpha 0 is the published linear row, refitted by this code as the paired reference.
"""
import argparse
import json
from pathlib import Path
import shutil
import time

import numpy as np

from neuroworld.benchmark import forecast as F, grid as G, profile as P, state as S, updating as U
from neuroworld.benchmark.grid import frames_within
from neuroworld.benchmark.references import SpatialBasis, StimulusRidge, _accumulate, _group, _moments, _solve
from neuroworld.experiments.history_length import BUDGETS, CONFIGS, LONGEST, Window, WindowLinear
from neuroworld.paths import OUTPUT

RUNS = OUTPUT / "checkpoints/algonauts/wave2_20261102"
STORE = OUTPUT / "benchmark-test"  # probes and the stimulus-row cache with the test films, read only
SAVED = OUTPUT / "paper-analysis"   # collect.py's saved forecasts (check)
TEACHERS = {("spectator", 7.5): ("ridge-jepa-7.5s-std-partial", 7.5), ("spectator", 180.0): ("ridge-jepa-180s-std-partial", 180.0),
            ("movie", 7.5): ("ridge-jepa-180s-std-partial-nofmri", 180.0), ("movie", 180.0): ("ridge-jepa-180s-std-partial-nofmri", 180.0)}
SPLITS = ("val", "dev", "test")
log = lambda text: print(text, flush=True)




class Teacher:
    """A latent row (collect.latent_row) with its stored probe: forecasts [n, H, 1000] from any recording's real fMRI."""

    def __init__(self, arm, seconds, data, device="cuda", run_dir=None, probe_path=None):
        """arm: a run in RUNS with its probe in STORE, or any run directory and probe file (run_dir, probe_path)."""
        from neuroworld.benchmark.adapters import ProbeHead, RolloutAdapter
        from neuroworld.benchmark.latent import LatentProbe, Probe
        from neuroworld.train.readout import load_world_model
        from neuroworld.utils.config import load_config
        run_dir = Path(run_dir or RUNS / arm)
        probe_path = Path(probe_path or STORE / data.dataset / "probes" / f"{arm}.npz")
        cfg = load_config(run_dir / "config.yaml")
        model, _ = load_world_model(cfg, run_dir / "best.pt", device)
        probe = Probe.__new__(Probe)
        with np.load(probe_path, allow_pickle=False) as saved:
            probe.meta = json.loads(str(saved["meta"]))
            probe.weights = {g: (saved[f"W {i}"], saved[f"b {i}"]) for i, g in enumerate(probe.meta["groups"])}
        probe.dataset, probe.open_loop_only, probe.alpha = data.dataset, False, probe.meta["penalty"]
        probe.provenance = {"probe": str(probe_path)}
        adapter = RolloutAdapter(arm, model, ProbeHead(probe), cfg, device,
                                 getattr(model, "read_states", cfg["model"]["context_states"]) * getattr(model, "state_step", 1))
        self.row, self.data, self.name = LatentProbe(adapter, probe, f"{arm} (latent)"), data, arm
        self.frames = frames_within(seconds, data.grid.tr)

    def forecast(self, run, origins, horizon):
        return F.predict(self.row, self.data.dataset, self.data.grid.tr, run, origins, self.frames, horizon)


class Student(WindowLinear):
    """WindowLinear whose step-k target at starting point t0 is (1 - alpha) * fMRI + alpha * the teacher's forecast (module docstring)."""

    def __init__(self, data, stimulus, seconds, basis, teacher, alpha, log=log):
        self.teacher, self.alpha, self.teacher_fit = teacher, alpha, {}
        super().__init__(data, stimulus, seconds, basis, log)

    def _fit(self, frames):
        H, stats = self.horizon, {}
        se = ref = 0.0
        anchors_total = 0
        for run in self.data.runs("train"):
            anchors, prefix = self._prefixes(run, frames)
            if not len(anchors):
                continue
            h = self._features(prefix).astype(np.float64)
            frames_ok, values = self.targets[run.run_id]
            target = np.zeros(run.n, dtype=bool)
            target[frames_ok] = True
            residual = np.zeros((run.n, 1000))
            residual[frames_ok] = values
            g = stats.setdefault(_group(self.data, run.subject_id), _moments(h.shape[1], H, residual.shape[1]))
            t = anchors[:, None] + np.arange(H)[None]
            ok = t < run.n
            ok[ok] = target[t[ok]]
            tc = np.minimum(t, run.n - 1)
            r = residual[tc]  # [anchors, H, 1000] fMRI minus the stimulus ridge's prediction
            if self.alpha:
                y = np.asarray(run.brain[:], dtype=np.float64)[tc]
                f = self.teacher.forecast(run, anchors, H).astype(np.float64)
                r += self.alpha * (f - y)  # (1 - a) fMRI + a forecast, minus the same stimulus prediction
                se += float((((f - y) ** 2) * ok[..., None]).sum())
                mean = y[ok].mean(0) if ok.any() else 0.0
                ref += float((((mean - y) ** 2) * ok[..., None]).sum())
            anchors_total += len(anchors)
            _accumulate(g, h, r * ok[..., None], ok)
        if self.alpha:
            in_sample = round(100 * (1 - se / max(ref, 1e-12)), 2)
            self.teacher_fit = {"training anchors": anchors_total, "teacher skill on the training targets (%)": in_sample}
            log(f"{self.name}: teacher {self.teacher.name} on {anchors_total} training anchors, in-sample skill {in_sample}")
        return {group: _solve(g) for group, g in stats.items()}


def row_name(seconds, teacher, alpha, tag=None):
    base = f"linear [context] {seconds:g} s"
    return base + (", real" if not alpha else f", {teacher} targets a{alpha:g}") + (f", {tag}" if tag else "")


def fit_file(name):
    return name.replace("linear [context] ", "").replace(", ", "-").replace(" ", "")


def fit(args):
    import resource  # the teacher's movie-row reader keeps every file it opens memory-mapped: over 1,024 on the training runs
    resource.setrlimit(resource.RLIMIT_NOFILE, (resource.getrlimit(resource.RLIMIT_NOFILE)[1],) * 2)
    root = Path(args.out)
    cache = root / "algonauts" / "stimulus-rows-context.npz"
    if not cache.is_file():
        cache.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy(STORE / "algonauts" / "stimulus-rows-context.npz", cache)
    G.HISTORY_SECONDS = LONGEST  # as history_length.run: every query carries 240 s, the student reads its last L
    U.BUDGETS = BUDGETS
    from neuroworld.benchmark.data import BenchmarkData
    data = BenchmarkData(args.data_config or CONFIGS["algonauts"])  # a config with fewer training runs fits on those only
    seconds = float(args.seconds)
    teacher = None
    if args.alpha:
        if args.teacher_run:  # any run directory and probe file, e.g. Spectator retrained on fewer recordings
            arm, teacher_seconds = Path(args.teacher_run).name, args.teacher_seconds or seconds
            teacher = Teacher(arm, teacher_seconds, data, args.device, run_dir=args.teacher_run, probe_path=args.teacher_probe)
        else:
            arm, teacher_seconds = TEACHERS[(args.teacher, seconds)]
            teacher = Teacher(arm, teacher_seconds, data, args.device)
    started = time.time()
    stimulus = StimulusRidge(data, cache=cache, log=log, features="context")
    student = Student(data, stimulus, seconds, SpatialBasis(data), teacher, args.alpha)
    name = row_name(seconds, args.teacher, args.alpha, args.tag)
    model = Window(student, seconds, name)
    log(f"{name}: fitted in {time.time() - started:.0f}s")
    for split in SPLITS:
        F.run(data, model, split, output=root, log=log)
    sums = {"dev": S.collect(data, model, data.runs(S.GROUPS[data.dataset]["dev"][0]), None, log, S.GROUPS[data.dataset]["dev"][1])}
    S.save(root / data.dataset / "state", model.name, {"model": model.name, "stamp": G.stamp()}, sums)
    if seconds <= 30:
        U.run(data, model, splits=SPLITS, output=root, log=log)
    meta = {"row": name, "seconds": seconds, "teacher": None if not args.alpha else (args.teacher_run or TEACHERS[(args.teacher, seconds)][0]),
            "alpha": args.alpha, "data_config": args.data_config,
            "selection": student.selection, **student.teacher_fit, "minutes": round((time.time() - started) / 60, 1)}
    (root / "fits").mkdir(parents=True, exist_ok=True)
    (root / "fits" / f"{fit_file(name)}.json").write_text(json.dumps(meta, indent=1, default=float))
    log(f"{name}: finished in {time.time() - started:.0f}s")


def check(args):
    """Each Spectator teacher reproduces collect.py's saved forecasts on the first validation recordings."""
    from neuroworld.benchmark.data import BenchmarkData
    data = BenchmarkData(CONFIGS["algonauts"])
    runs = {r.run_id.replace("/", "__"): r for r in data.runs("val")}
    for (kind, seconds), folder in (((("spectator", 180.0)), "spectator"), ((("spectator", 7.5)), "spectator7.5")):
        arm, teacher_seconds = TEACHERS[(kind, seconds)]
        teacher = Teacher(arm, teacher_seconds, data, args.device)
        worst = 0.0
        for path in sorted((SAVED / folder / "val").glob("*.npz"))[:args.runs]:
            saved = np.load(path, allow_pickle=True)
            pred = teacher.forecast(runs[path.stem], saved["origins"], saved["pred"].shape[1])
            diff = float(np.abs(pred - saved["pred"].astype(np.float32)).max())
            worst = max(worst, diff)
            log(f"{arm}: {path.stem} largest difference {diff:.2e} (forecast scale {float(np.abs(pred).mean()):.3f})")
        log(f"{arm}: worst {worst:.2e} over {args.runs} recordings (saved forecasts are float16)")


def report(args):
    root = Path(args.out)
    P.ROOT = root
    names = sorted({p.parent.name for p in (root / "algonauts").glob("*/*/results.json")})
    skill = lambda u: None if not u else 100 * (1 - sum(v[0] for v in u.values()) / sum(v[1] for v in u.values()))
    rows = {}
    for name in names:
        rows[name] = {"Forecast": P._unit_sums("forecast", "algonauts", list(SPLITS), name), "State": P._unit_sums("state", "algonauts", ["dev"], name),
                      "Updating": P._unit_sums("updating", "algonauts", list(SPLITS), name)}
    out = {}
    for name, cells in rows.items():
        base = name.split(", ")[0] + ", real"
        line = {k: None if v is None else round(skill(v), 2) for k, v in cells.items()}
        if name != base and base in rows:
            for k in ("Forecast", "State", "Updating"):
                if cells[k] and rows[base][k]:
                    d = P._paired(cells[k], rows[base][k])
                    line[f"{k} minus real"] = None if d is None else {x: round(d[x], 2) for x in ("value", "low", "high")}
        out[name] = line
        log(f"{name}: {json.dumps(line)}")
    (root / "results.json").write_text(json.dumps(out, indent=1))


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    f = sub.add_parser("fit")
    f.add_argument("--seconds", type=float, required=True)
    f.add_argument("--teacher", choices=("spectator", "movie"), default="spectator")
    f.add_argument("--alpha", type=float, default=0.0)
    f.add_argument("--out", required=True)
    f.add_argument("--device", default="cuda")
    f.add_argument("--data-config", help="Benchmark dataset config (default the package's), e.g. one with fewer training runs")
    f.add_argument("--teacher-run", help="Teacher run directory (config.yaml, best.pt) in place of --teacher's stored model")
    f.add_argument("--teacher-probe", help="The teacher's probe file (with --teacher-run)")
    f.add_argument("--teacher-seconds", type=float, help="The teacher's history (with --teacher-run; default --seconds)")
    f.add_argument("--tag", help="Appended to the row name")
    c = sub.add_parser("check")
    c.add_argument("--runs", type=int, default=3)
    c.add_argument("--device", default="cuda")
    r = sub.add_parser("report")
    r.add_argument("--out", required=True)
    args = parser.parse_args()
    {"fit": fit, "check": check, "report": report}[args.command](args)
